sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float threshold;
uniform float blur;
uniform float spread;
layout(color) uniform half4 color;
uniform float blend;
uniform float invert;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
float edgesImage( float2 at, float step_) {
    float l = luma(float3(image.eval(at + float2(-step_, 0.0)).rgb));
    float r = luma(float3(image.eval(at + float2(step_, 0.0)).rgb));
    float u = luma(float3(image.eval(at + float2(0.0, -step_)).rgb));
    float d = luma(float3(image.eval(at + float2(0.0, step_)).rgb));
    float al = float(image.eval(at + float2(-step_, 0.0)).a);
    float ar = float(image.eval(at + float2(step_, 0.0)).a);
    float au = float(image.eval(at + float2(0.0, -step_)).a);
    float ad = float(image.eval(at + float2(0.0, step_)).a);
    return length(float2(r - l, d - u)) + length(float2(ar - al, ad - au));
}
float edgesBlurred( float2 at, float step_) {
    float l = luma(float3(blurred.eval(at + float2(-step_, 0.0)).rgb));
    float r = luma(float3(blurred.eval(at + float2(step_, 0.0)).rgb));
    float u = luma(float3(blurred.eval(at + float2(0.0, -step_)).rgb));
    float d = luma(float3(blurred.eval(at + float2(0.0, step_)).rgb));
    float al = float(blurred.eval(at + float2(-step_, 0.0)).a);
    float ar = float(blurred.eval(at + float2(step_, 0.0)).a);
    float au = float(blurred.eval(at + float2(0.0, -step_)).a);
    float ad = float(blurred.eval(at + float2(0.0, step_)).a);
    return length(float2(r - l, d - u)) + length(float2(ar - al, ad - au));
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    float sharp = edgesImage(coord, 1.0);
    float soft = edgesBlurred(coord, max(blur * 0.25, 1.0)) * max(blur * 0.25, 1.0) * 0.5;
    float e = max(sharp - threshold, 0.0) * 2.0 + max(soft - threshold * 0.5, 0.0) * spread;
    if (invert > 0.5) e = 1.0 - clamp(e, 0.0, 1.0);
    e = clamp(e, 0.0, 1.0);
    float a = float(src.a);
    float3 base = a > 0.0 ? float3(src.rgb) / a : float3(0.0);
    float3 under = base * clamp(blend, 0.0, 2.0) * 0.5;
    float3 glow = float3(color.rgb) * e * float(color.a);
    float3 rgb = clamp(under + glow, 0.0, 1.0) * a + glow * (1.0 - a);
    return half4(half3(rgb), half(a + e * (1.0 - a)));
}
